export const LZ4_MAGIC=[229,161,237,254];export function hasMagic(e,n=0){return e.length>=n+4&&e[n]===LZ4_MAGIC[0]&&e[n+1]===LZ4_MAGIC[1]&&e[n+2]===LZ4_MAGIC[2]&&e[n+3]===LZ4_MAGIC[3]}export function lz4DecompressBlock(e,n){const f=new Uint8Array(n);let t=0,l=0;const a=e.length;for(;t<a;){const c=e[t++];let o=c>>>4;if(o===15){let r;do r=e[t++],o+=r;while(r===255)}if(o>0&&(f.set(e.subarray(t,t+o),l),t+=o,l+=o),t>=a)break;const i=e[t]|e[t+1]<<8;if(t+=2,i===0)throw new Error("LZ4: invalid offset 0");let h=(c&15)+4;if((c&15)===15){let r;do r=e[t++],h+=r;while(r===255)}let u=l-i;if(u<0)throw new Error("LZ4: offset before buffer start");if(l+h>n)throw new Error("LZ4: match exceeds destination size");for(let r=0;r<h;r++)f[l++]=f[u++]}if(l!==n)throw new Error(`LZ4: decompressed size ${l} != expected ${n}`);return f}function w(e,n){return(e[n]|e[n+1]<<8|e[n+2]<<16|e[n+3]<<24)>>>0}import{MAX_CHUNK_DECOMP_BYTES as d,MAX_TOTAL_DECOMP_BYTES as x,MAX_CHUNKS as m}from"./limits.min.js";export function decodeChunks(e){const n=[];let f=0,t=0,l=0;for(;t<e.length&&hasMagic(e,t);){const i=w(e,t+4),h=w(e,t+8);if(t+=16,i===0||t+i>e.length||h===0||h>d||++l>m||f+h>x)throw new Error("LZ4: incoherent chunk header or aberrant volume, not an NMS save");const u=e.subarray(t,t+i);t+=i;const r=lz4DecompressBlock(u,h);n.push(r),f+=r.length}let a=new Uint8Array(f),c=0;for(const i of n)a.set(i,c),c+=i.length;let o=a.length;for(;o>0&&a[o-1]===0;)o--;return a.subarray(0,o)}
